<?php
/**
 * Isologo de la casa para la encuesta: CASA sobre PESTALOZZI y, debajo, el
 * filete de oro partido por el medallón CP — la composición del hero
 * (views/home/_hero.php), a escala de membrete.
 *
 * Las letras NO se escriben con KudosKaps: son los trazos de
 * views/admin/menu/_isologo.svg, que scripts/isologo-pdf.py genera desde el
 * .otf con el tracking (0.03 em) y la interlínea (1.02 em) del hero. Antes la
 * vista escribía «Casa Pestalozzi» en caja mixta con la fuente, y KudosKaps es
 * de versales: sus minúsculas son versalitas, así que salía «Cᴀsᴀ Pᴇsᴛᴀʟᴏᴢᴢɪ»
 * en una sola línea, con otro tracking y sin filete ni medallón — un logotipo
 * que el manual no tiene. Con el trazo no hay salto de cara mientras carga la
 * fuente, ni peso sintético posible, ni proporción que dependa del navegador;
 * y la pantalla se ahorra los 71 KB del .otf, que sólo pedía el logotipo.
 *
 * El medallón es copia literal del del hero (los mismos trazos de la C y la P
 * de KudosKaps, la misma elipse). Si el hero cambia su medallón, éste lo sigue.
 * Sólo los grosores de línea son otros, y a propósito: el del hero se dibuja a
 * 60 px de ancho y aquí a unos 15, donde un trazo de 1.6 unidades se queda en
 * medio píxel y la corona punteada desaparece.
 *
 * Ningún color está escrito aquí: cada pieza pide su --fb-iso-* desde
 * _feedback.scss, que los deriva de la capa 1, así que el isologo sigue a la
 * paleta editable de Configuración igual que el del hero.
 *
 * Si el archivo de trazos faltara, cae a texto en KudosKaps con la misma
 * composición (CASA sobre PESTALOZZI): peor, porque depende de la fuente,
 * pero nunca un hueco.
 */

$isoCaja = '';
$isoTrazo = '';
$isoAncho = 0;
$isoAlto = 0;
$isoFuente = __DIR__ . '/../admin/menu/_isologo.svg';

if (is_readable($isoFuente)) {
    $isoSvg = (string) file_get_contents($isoFuente);
    if (preg_match('/viewBox="0 0 ([\d.]+) ([\d.]+)"/', $isoSvg, $isoVb)
        && preg_match('/\sd="([^"]+)"/', $isoSvg, $isoD)) {
        $isoAncho = (float) $isoVb[1];
        $isoAlto = (float) $isoVb[2];
        $isoCaja = '0 0 ' . $isoVb[1] . ' ' . $isoVb[2];
        $isoTrazo = $isoD[1];
    }
}
?>
<div class="fb-isologo" role="img" aria-label="Casa Pestalozzi">
  <?php if ($isoTrazo !== '') : ?>
    <?php /* width/height en las unidades del viewBox sólo para fijar la
             proporción: el tamaño lo pone el CSS (ancho en em, alto auto), así
             que las letras nunca se estiran. */ ?>
    <svg class="fb-isologo__nombre" viewBox="<?php echo htmlspecialchars($isoCaja, ENT_QUOTES, 'UTF-8'); ?>"
         width="<?php echo (int) round($isoAncho); ?>" height="<?php echo (int) round($isoAlto); ?>"
         aria-hidden="true" focusable="false"><path d="<?php echo htmlspecialchars($isoTrazo, ENT_QUOTES, 'UTF-8'); ?>"/></svg>
  <?php else : ?>
    <span class="fb-isologo__texto" aria-hidden="true">
      <span class="fb-isologo__casa">CASA</span>
      <span class="fb-isologo__pestalozzi">PESTALOZZI</span>
    </span>
  <?php endif; ?>
